import pathlib,base64,hashlib,json,subprocess,os
root=pathlib.Path('/content/mathvisionkid_t4_budget_3h_20261023')
payload={'training/collect_final_evidence.py': '', 'training/build_final_quality_report.py': '', 'evaluation/review_aggregation.py': '', 'evaluation/compare_adapter_review.py': '', 'final_evidence_archive_runtime.py': ''}
proofs={}
for name,b64 in payload.items():
 p=root/name;p.parent.mkdir(parents=True,exist_ok=True);raw=base64.b64decode(b64)
 if p.exists() and p.read_bytes()!=raw:raise ValueError('codefileexistswithdifferentbytes:'+name)
 p.write_bytes(raw);proofs[name]=hashlib.sha256(raw).hexdigest()
print(json.dumps({'deployed_code_only':proofs,'training_unchanged':True}))
